import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { Game } from './game/Game.tsx';

const root = document.getElementById('root');
if (!root) throw new Error('Missing application root.');
createRoot(root).render(
  <StrictMode>
    <Game />
  </StrictMode>,
);
import { useRef } from 'react';
import { Board } from './board/Board.tsx';
import { Controls } from './controls/Controls.tsx';
import { Reproduction } from './controls/Reproduction.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { useGame } from './session/use-game.ts';
import './game.css';

export function Game() {
  const controller = useGame();
  const { session } = controller;
  const { game } = session;
  const board = useRef<BoardFocus>(null);
  function resume(): void {
    board.current?.focusRemembered();
    controller.resume();
  }
  return (
    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <p className="intro">Reveal two cards. Match their shape and marker to keep the pair.</p>
      <Controls size={game.size} newGame={controller.newGame} restart={controller.restart} />
      <GameStatus
        game={game}
        best={session.preferences.bestMoves[String(game.size)]}
        celebration={session.celebration}
      />
      <p id="board-help" className="help">
        Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
        reveals a card.
      </p>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={session.announcement}>{session.feedback}</span>
        </p>
      </div>
      <Board key={session.generation} game={game} activate={controller.activate} ref={board} />
      <Reproduction
        game={game}
        generation={session.generation}
        exportSnapshot={controller.exportSnapshot}
        loadBoard={controller.loadBoard}
        loadSnapshot={controller.loadSnapshot}
        notice={session.loadNotice}
        paused={session.paused}
        resume={resume}
      />
    </main>
  );
}
import { expect, test } from './browser-test.ts';
import { loadFixedBoard, exportedSnapshot } from './game-fixture.ts';

const COLOR_VECTOR = {
  page: 'rgb(9, 11, 20)',
  panel: 'rgb(20, 24, 39)',
  back: 'rgb(27, 32, 52)',
  face: 'rgb(17, 22, 37)',
  text: 'rgb(244, 246, 255)',
  secondary: 'rgb(184, 189, 210)',
  border: 'rgb(117, 124, 154)',
  focus: 'rgb(255, 255, 255)',
};

test('layout, typography, colors and card geometry match the product values', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 800 });
  await loadFixedBoard(page);
  const style = await page.evaluate(() => {
    const get = (selector: string) => {
      const element = document.querySelector(selector);
      if (!element) throw new Error('Missing style target.');
      return getComputedStyle(element);
    };
    return {
      page: get(':root').backgroundColor,
      text: get(':root').color,
      panel: get('.board-viewport').backgroundColor,
      back: get('.card').backgroundColor,
      border: get('.card').borderColor,
      secondary: get('.help').color,
      bodySize: get(':root').fontSize,
      bodyLine: get(':root').lineHeight,
      titleSize: get('h1').fontSize,
      secondarySize: get('.help').fontSize,
      introSize: get('.intro').fontSize,
      padding: get('main').padding,
      maximum: get('main').maxWidth,
      gap: get('.board').gap,
      cardBorder: get('.card').borderWidth,
      radius: get('.card').borderRadius,
    };
  });
  expect(style).toEqual({
    page: COLOR_VECTOR.page,
    text: COLOR_VECTOR.text,
    panel: COLOR_VECTOR.panel,
    back: COLOR_VECTOR.back,
    border: COLOR_VECTOR.border,
    secondary: COLOR_VECTOR.secondary,
    bodySize: '16px',
    bodyLine: '24px',
    titleSize: '24px',
    secondarySize: '14px',
    introSize: '14px',
    padding: '16px',
    maximum: '1120px',
    gap: '6px',
    cardBorder: '2px',
    radius: '8px',
  });
  await page.locator('.card').first().focus();
  await page.keyboard.press('Enter');
  const focused = await page
    .locator('.card')
    .first()
    .evaluate((element) => {
      const style = getComputedStyle(element);
      return {
        face: style.backgroundColor,
        color: style.outlineColor,
        width: style.outlineWidth,
        offset: style.outlineOffset,
      };
    });
  expect(focused).toEqual({
    face: COLOR_VECTOR.face,
    color: COLOR_VECTOR.focus,
    width: '3px',
    offset: '2px',
  });
});

test('hover changes only card border color and matched marks stay legible', async ({ page }) => {
  await loadFixedBoard(page);
  await page.mouse.move(0, 0);
  const card = page.locator('.card').nth(2);
  const before = await card.evaluate((e) =>
    Object.fromEntries(
      [...getComputedStyle(e)].map((k) => [k, getComputedStyle(e).getPropertyValue(k)]),
    ),
  );
  const progress = await exportedSnapshot(page);
  await card.hover();
  await expect(card).toHaveCSS('border-color', 'rgb(244, 246, 255)');
  const after = await card.evaluate((e) =>
    Object.fromEntries(
      [...getComputedStyle(e)].map((k) => [k, getComputedStyle(e).getPropertyValue(k)]),
    ),
  );
  const changed = Object.keys(before).filter((k) => before[k] !== after[k]);
  expect(changed.length).toBeGreaterThan(0);
  expect(
    changed.filter(
      (k) =>
        !/^border-(?:(?:top|right|bottom|left|block(?:-start|-end)?|inline(?:-start|-end)?)-)?color$/.test(
          k,
        ),
    ),
  ).toEqual([]);
  expect(await exportedSnapshot(page)).toEqual(progress);
  await card.click();
  await page.locator('.card').nth(6).click();
  await expect(page.locator('.stats dd').nth(1)).toHaveText('1/8');
  await page.mouse.move(0, 0);
  await expect(card).toHaveCSS('border-color', 'rgb(139, 234, 125)');
  await expect(card).toHaveCSS('opacity', '1');
  const mark = card.locator('.matched-mark');
  await expect(mark).toBeVisible();
  await expect(mark.locator('path')).toHaveAttribute('d', 'm2 6 3 3 5-6');
});
import { readFile } from 'node:fs/promises';
import { expect, test } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadTimedBoard } from './game-fixture.ts';

test('status formats show current values, continuing minutes and a completed import without Resume', async ({
  page,
}) => {
  const initial: string[] = [];
  await loadTimedBoard(page);
  // Rendered text shows whether each value sits on its label's line.
  const status = () =>
    page.locator('.stats > div').evaluateAll((elements) =>
      elements.map((element) => {
        if (!(element instanceof HTMLElement)) throw new Error('Expected a rendered status.');
        return element.innerText;
      }),
    );
  initial.push(...(await status()));
  for (const index of EXAMPLE_PAIRS[0]) await page.locator('.card').nth(index).click();
  const matched = await status();
  await page.locator('summary').click();
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(
    JSON.stringify({
      version: 1,
      boardCode: 'np1-4-1',
      matched: EXAMPLE_PAIRS.flat(),
      selection: { kind: 'closed' },
      moves: 8,
      elapsedMs: 3_600_999,
      started: true,
    }),
  );
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  const loaded = await status();
  await expect(
    page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
  ).toHaveCount(0);
  await expect(page.getByRole('status')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.load-notice')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.victory.celebrate')).toHaveCount(0);
  await page.clock.runFor(2000);
  expect(await status()).toEqual(loaded);
  const expected: unknown = JSON.parse(
    await readFile(new URL('./status-format.fixture.json', import.meta.url), 'utf8'),
  );
  expect({ initial, matched, loaded }).toEqual(expected);
});

test('the Board code control trims surrounding whitespace and both successful load types select their size', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const board = page.getByLabel(ReproductionControl.board, { exact: true });
  await board.fill('  np1-6-1  ');
  await board.press('Enter');
  await expect(board).toHaveValue('np1-6-1');
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
  await expect(page.locator('.card')).toHaveCount(36);
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(
    JSON.stringify({
      version: 1,
      boardCode: 'np1-8-1',
      matched: [],
      selection: { kind: 'closed' },
      moves: 0,
      elapsedMs: 0,
      started: false,
    }),
  );
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('8');
  await expect(page.locator('.card')).toHaveCount(64);
  await expect(
    page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
  ).toBeVisible();
});

test('named color targets, reset margins and card focus scroll margins follow the visual contract', async ({
  page,
}) => {
  await loadTimedBoard(page);
  for (const selector of [
    '.board-viewport',
    '.reproduction',
    'button',
    'select',
    'input',
    'textarea',
  ]) {
    await expect(page.locator(selector).first()).toHaveCSS('background-color', 'rgb(20, 24, 39)');
  }
  await expect(page.locator('body')).toHaveCSS('margin', '0px');
  for (const selector of ['.eyebrow', '.help', '.intro', '.stats dt']) {
    const secondary = page.locator(selector).first();
    await expect(secondary, `V08 secondary size ${selector}`).toHaveCSS('font-size', '14px');
    await expect(secondary, `V06 secondary color ${selector}`).toHaveCSS(
      'color',
      'rgb(184, 189, 210)',
    );
  }
  const card = page.locator('.card').nth(EXAMPLE_PAIRS[0][0]);
  const margin = await card.evaluate((element) => getComputedStyle(element).scrollMargin);
  expect(parseFloat(margin)).toBeGreaterThanOrEqual(6);
  await card.hover();
  await page.clock.runFor(120);
  await expect(card).toHaveCSS('border-color', 'rgb(244, 246, 255)');
  await card.click();
  const main = card.locator('svg g');
  const marker = card.locator('svg > circle');
  await expect(main).toHaveAttribute('fill', '#63E7FF');
  await expect(marker).toHaveAttribute('fill', '#63E7FF');
  await expect(marker).toHaveAttribute('stroke', 'var(--face)');
  await page.locator('.card').nth(EXAMPLE_PAIRS[0][1]).click();
  await card.hover();
  await page.clock.runFor(120);
  await expect(card).toHaveCSS('border-color', 'rgb(139, 234, 125)');
  await expect(card.locator('.matched-mark')).toHaveCSS('color', 'rgb(139, 234, 125)');
});
"}

